const o=[{question:"מהי המשמעות הספרותית של הצגת איוב כמי שמתגורר ב'ארץ עוץ' ונמנה עם 'בני קדם'?",options:["הדבר מעיד על כך שאיוב היה מלך היסטורי ששלט באזור אדום המקראית.","הדבר מדגיש את היותו דמות אוניברסלית הקשורה למסורות חכמה בינלאומיות.","הדבר נועד לקשור את איוב באופן ישיר לשושלת בית דוד ולמלכות יהודה.","הדבר מרמז שאיוב היה נביא שנשלח להחזיר את עמי המזרח בתשובה."],correctAnswer:1,explanation:"איוב מוצג כדמות שאינה ישראלית (ארץ עוץ, בני קדם), מה שמקנה לסיפור אופי אוניברסלי ומנתק אותו מההקשר הלאומי-היסטורי של ישראל. זה מאפשר דיון פילוסופי טהור בשאלת הצדק."},{question:"כיצד מתואר תפקידו של 'השטן' בפרקי הפתיחה של ספר איוב (א'-ב')?",options:["כישות דמונית עצמאית הנלחמת באלוהים על השליטה בעולם.","כמקור לכל הרוע והחטאים המוסריים של בני האדם עלי אדמות.","כקטגור בבית הדין האלוהי, הכפוף לאל ופועל בשירותו לבחינת הנאמנות.","כדמות סמלית המייצגת את יצרו הרע ואת מחשבותיו הפנימיות של איוב."],correctAnswer:2,explanation:"השטן בספר איוב אינו השטן הנוצרי (ישות המורדת באל) אלא מלאך ב'בני האלוהים' שתפקידו לשוטט בארץ ולבחון את נאמנות בני האדם (כמו 'קטגור' או תובע)."},{question:"מהי הטענה המרכזית העומדת בבסיס ה'התערבות' בין השטן לאלוהים?",options:["אמונתו של איוב היא שברירית ותלויה לחלוטין בשגשוגו הכלכלי ובבריאותו.","לא ניתן למצוא צדיק אמיתי בארץ שאינו חוטא בסתר ליבו.","אלוהים אינו מודע למחשבותיהם האמיתיות של בני האדם וזקוק למבחן חיצוני.","איוב עובד את אלוהים מתוך פחד מעונש ולא מתוך אהבת הטוב."],correctAnswer:0,explanation:"השטן טוען שיושרו של איוב תלוי בדבר ('החינם ירא איוב אלוהים?'). אם ייקח ממנו את הברכה, איוב יקלל אותו. כלומר, הצדיקות תלויה בתגמול."},{question:"במה שונה קללת היום של איוב (פרק ג') מקללת היום של ירמיהו (פרק כ')?",options:["ירמיהו מקלל את הוריו, בעוד איוב מתמקד אך ורק ביום הולדתו.","איוב מבקש לבטל את הבריאה ולהחזיר את העולם לתוהו ובוהו, בניגוד לירמיהו שמביע צער אישי.","ירמיהו משתמש בדימויים מיתולוגיים של לוויתן וים, בעוד איוב משתמש בשפה ריאליסטית.","קללתו של איוב נובעת מחטא שחטא, בעוד קללתו של ירמיהו נובעת מרדיפה דתית."],correctAnswer:1,explanation:"איוב משתמש בשפה קוסמית ומיתולוגית ('יאבד יום...', 'יקברוהו אנשי יום') כדי לבקש את ביטול הבריאה כולה, בעוד ירמיהו מקלל את יום לידתו באופן אישי ונקודתי יותר."},{question:"מהי הטענה הייחודית של אליפז בניסיונו להסביר את סבלו של איוב?",options:["הסבל הוא אשליה זמנית שנועדה לבחון את סבלנותו של הצדיק.","אלוהים מייסר את האדם כ'מוסר' (חינוך) כדי לנקותו מחטא ולשפרו.","הסבל נגרם בשל חטאי בניו של איוב ולא בשל מעשיו שלו.","אין כל היגיון בסבל, ועל האדם לקבל את שרירותיות הגורל בהכנעה."],correctAnswer:1,explanation:"אליפז מציג את תפיסת 'המוסר' - 'אשרי אנוש יוכיחנו אלוה'. הסבל אינו עונש על פשע נורא אלא חינוך ('מוסר אב') שנועד לנקות את האדם."},{question:"כיצד משתמש בלדד במשל 'גומא ומי הים' (הצמחים)?",options:["כדי להוכיח שהאדם תלוי בחסדי האל כמו שהצמח תלוי במים.","כדי להדגים את שגשוגו המהיר של הרשע, שסופו לקמול ולהיעלם בפתאומיות.","כדי לטעון שגם אם איוב נכרת כרגע, הוא עתיד לצמוח מחדש כמו עץ.","כדי להמחיש את היופי שבבריאה ואת דאגתו של האל לכל עשב השדה."],correctAnswer:1,explanation:"בלדד משתמש במשל הצמחים (גומא, אחו) הגדלים מהר אך קמלים במהירות ללא מים, כדי לתאר את גורל הרשעים (שוכחי אל) שנראה כאילו הם מצליחים, אך סופם אבדון מהיר."},{question:"מהי תגובתו של איוב לטיעון ה'מוסר' (החינוך) של אליפז?",options:["איוב טוען שהוא זקן וחולה מכדי ללמוד לקח, וסביר שימות במהלך ה'חינוך'.","איוב מקבל את הדין ומודה שאכן יש לו חטאים נסתרים הדורשים תיקון.","איוב טוען שאליפז אינו חכם מספיק כדי להבין את דרכי האל בחינוך האדם.","איוב מסביר שהמוסר האלוהי מיועד לרשעים בלבד ולא לצדיקים כמוהו."],correctAnswer:0,explanation:"איוב עונה: 'הכוח אבנים כוחי?'. הוא טוען שהסבל כה קשה ובלתי נסבל שהוא ימות לפני שילמד את הלקח, ולכן הטיעון החינוכי אבסורדי."},{question:"כיצד הופך איוב את משל העץ של בלדד על פיו בנאומי התגובה שלו?",options:["הוא טוען שהעץ מסמל את הרשע שלעולם לא ייעקר, בניגוד לצדיק הנודד.","הוא טוען שלעץ יש תקווה להתחדש לאחר שנכרת, אך לאדם המת אין תקווה לשוב.","הוא מדגיש שהעץ זקוק למים רבים, ואילו האדם יכול להסתפק במועט.","הוא משתמש בעץ כדימוי לאלוהים אשר מצל על ברואיו אך לפעמים מסתיר את השמש."],correctAnswer:1,explanation:"איוב משתמש בדימוי העץ של בלדד כדי להראות את חוסר התקווה של האדם: 'כי יש לעץ תקווה... אבל גבר ימות ויחלש'. לעץ יש מחזוריות, לאדם יש רק ירידה אל שְאוֹל."},{question:"מה מבקש איוב כשהוא טוען 'לֹא יֵשׁ בֵּינֵינוּ מוֹכִיחַ יָשֵׁת יָדוֹ עַל שְׁנֵינוּ' (ט', 33)?",options:["הוא מבקש נביא שיגלה לו את חטאו הספציפי.","הוא מייחל לגורם שלישי, בורר אובייקטיבי, שיוכל לגשר בינו לבין הכוח הבלתי מוגבל של האל.","הוא מתלונן על כך שחבריו אינם מוכיחים אותו בצורה קשה וכנה מספיק.","הוא מביע משאלה שאלוהים יתגלה אליו ישירות ללא מתווכים כלל."],correctAnswer:1,explanation:"איוב מרגיש שאינו יכול להישפט מול אלוהים כי יחסי הכוחות אינם שווים. הוא זקוק ל'מוכיח' (בורר/מתווך) שיוכל להניח ידו על שניהם ולייצר הליך הוגן."},{question:"מדוע, על פי חומרי הלימוד, מקצינים הרעים את האשמותיהם כלפי איוב ככל שהוויכוח מתקדם?",options:["הם מגלים במהלך הדיון ראיות חדשות ומרשיעות על עברו של איוב.","הם נעלבים מהסגנון הבוטה של איוב ומחליטים להעליב אותו בחזרה.","כדי להגן על 'תורת הגמול' והסדר האלוהי, הם נאלצים להמציא לאיוב חטאים בדיעבד.","הם מנסים לגרום לאיוב לקלל את אלוהים ובכך להוכיח את טענת השטן."],correctAnswer:2,explanation:"כדי לשמור על התיאולוגיה שלהם (אלוהים צודק, האדם חוטא), הם חייבים למצוא חטא אצל איוב. מכיוון שאיוב מתעקש על חפותו, הם נאלצים להמציא לו פשעים קונקרטיים (גזלת אלמנות וכו') כדי להצדיק את העונש."},{question:"מהו תפקידה של 'שבועת הניקוי' (פרק ל'א) באסטרטגיה המשפטית של איוב?",options:["לסיים את הדיון בהודאה באשמה וקבלת הדין כדי לפייס את הרעים.","ליצור מנגנון הלכתי שיאפשר לרעים לסלוח לו ולשוב לביתם.","לכפות על אלוהים תגובה: או שיעניש אותו מיידית על שבועת שקר, או שיודה בחפותו.","להוכיח לחברה שאיוב עדיין שומר על צלילות דעתו למרות הסבל הרב."],correctAnswer:2,explanation:"שבועת הניקוי היא כלי משפטי אחרון. אם איוב נשבע לשקר - האל חייב להעניש אותו מיד. אם לא - שתיקתו של האל היא כהודאה בחפותו. זהו מהלך ל'אילוץ' האל לענות."},{question:"כיצד מפרש מתתיהו צבת (Tsevat) את מענה אלוהים מן הסערה?",options:["המענה מלמד שהעולם הפיזי הוא א-מוסרי (Amoral), ואין לצפות מהטבע לפעול לפי חוקי הצדק.","המענה מוכיח שאיוב חטא בחטא הגאווה, ולכן נענש עד שילמד ענווה.","המענה מאשר את תורת הגמול ומבטיח לאיוב שכר כפול בעולם הבא.","המענה הוא למעשה הזמנה לאיוב להצטרף לצוות היועצים של האל בניהול העולם."],correctAnswer:0,explanation:"לפי צבת, התשובה היא שהעולם הפיזי (גשם, חיות טרף) לא פועל לפי חוקים מוסריים. הצדק הוא מושג אנושי, והטעות של איוב הייתה ציפייה מהקוסמוס להתנהג כמו בית משפט."},{question:"על פי אדוארד גרינשטיין (Greenstein), מהי המטרה העיקרית של נאום ה' מן הסערה?",options:["לנחם את איוב באמצעות הצגת היופי וההרמוניה של הבריאה.","לבצע מהלך משפטי של 'פסילת עד' על ידי ערעור זכותו של איוב להעיד על הנעשה בעולם.","ללמד את איוב זואולוגיה ומטאורולוגיה כדי להרחיב את אופקיו.","להודות בפני איוב שהשטן הוא האחראי הבלעדי לסבלו."],correctAnswer:1,explanation:"גרינשטיין טוען שהנאום הוא פורנזי-משפטי: אלוהים מנסה לקעקע את אמינותו של איוב כעד. הוא מראה שאיוב לא היה בבריאה ולא מבין איך דברים עובדים, ולכן עדותו על 'אי צדק' אינה קבילה."},{question:"במה מתמקדת פרשנותו של מייקל פוקס (Fox) למענה אלוהים?",options:["בטענה שהאל מתנצל בפני איוב על העוול שנגרם לו.","בגילוי שיש לעולם 'עצה' (תוכנית) וסדר, גם אם הם אינם פועלים לפי מנגנון גמול פשטני.","בכך שהלוויתן והבהמות מייצגים את כוחות הרשע שאלוהים עתיד להשמיד.","ברעיון שהסבל הוא אקראי לחלוטין ואין מאחוריו שום השגחה או כוונה."],correctAnswer:1,explanation:"פוקס מדגיש את המילה 'עצה' ('מי זה מחשיך עצה'). למרות הכאוס לכאורה, יש לעולם תוכנית (עיצוב, מבנה) וחוכמה פנימית, אך היא אינה סובבת סביב האדם."},{question:"מה מסמלים 'בהמות ולוויתן' בתשובת אלוהים לאיוב?",options:["כוחות כאוס שהאל גאה ביצירתם ובשליטתו עליהם, למרות שאינם מועילים לאדם.","סמלים לכוחות הרשע ההיסטוריים (מצרים ובבל) שישראל ינצח בעתיד.","יצורים מיתולוגיים שאלוהים נכשל בניסיון לאלף אותם ולכן הם משתוללים.","מקור המזון העתידי לצדיקים לעתיד לבוא."],correctAnswer:0,explanation:"אלוהים מציג בגאווה את המפלצות המיתולוגיות. הם לא 'רעים' שצריך להשמיד, אלא חלק מהבריאה הפראית. האל משחק עם הלוויתן, מה שמדגיש את שליטתו בכאוס."},{question:"מהי המשמעות של תיאור החיות (כגון הפרא והיען) בנאום האל?",options:["להראות שכל החיות נוצרו כדי לשרת את האדם ולספק את צרכיו.","להדגים קיומם של יצורים החיים במרחבים שאין בהם אדם, ולכן קיומם אינו תלוי במוסר האנושי.","להוכיח שאיוב אינו מכיר את שמות החיות ולכן אינו חכם.","לרמוז לאיוב שהוא מתנהג כמו חיה פראית שאינה מקבלת מרות."],correctAnswer:1,explanation:"החיות המתוארות (פרא, יען) חיות במדבר, רחוק מהאדם, ואינן מועילות לו. זה מוכיח שהבריאה אינה אנתרופוצנטרית (מרכזיות האדם) ושיש לה ערך גם ללא השיפוט המוסרי האנושי."},{question:"מהי 'החוויה האסתטית' או 'הנשגב הטראגי' לפי גישתה של קרול ניוסם (Newsom)?",options:["היכולת של איוב לכתוב שירה יפה מתוך הסבל.","השינוי התודעתי שאיוב עובר לנוכח עוצמת הבריאה, המייתר את הצורך בתשובה הגיונית.","היופי שבבגדי הכהונה של אהרון הכהן כפי שהם מתוארים בספר.","ההנאה של הקורא מהמבנה הספרותי המושלם של המסגרת והשירה."],correctAnswer:1,explanation:"ניוסם טוענת שהתשובה אינה בשכל אלא ברגש (The Sublime). איוב חווה את גודל הבריאה ועוצמתה, וזה מוציא אותו מההתמקדות בעוול האישי שלו אל התפעמות קוסמית."},{question:"כיצד מציג איוב את מצבו בפרק כ'ט (לפני שבועת הניקוי)?",options:["כרשע שחזר בתשובה וכעת סובל ייסורי מצפון.","כאדם שמעולם לא היה לו מעמד חברתי ולכן אין לו מה להפסיד.","כהתגלמות האידיאלית של החכמה והצדק החברתי שזכה לכבוד ולמעמד רם.","כמי שתמיד חשד שאלוהים יבגוד בו בסופו של דבר."],correctAnswer:2,explanation:"בפרק כ'ט איוב מתרפק על עברו. הוא לא רק היה עשיר, אלא מנהיג חברתי ומוסרי ('עיניים הייתי לעיוור...') שזכה לכבוד מלכים, מה שמעצים את הנפילה לכאב ולביזוי בפרק ל'."},{question:"מהי המסקנה המשותפת לרוב החוקרים (צבת, גרינשטיין, פוקס, ניוסם) לגבי ספר איוב?",options:["הספר מאשרר את תורת הגמול המסורתית (צדיק וטוב לו).","הספר דוחה את עקרון ה'מידה כנגד מידה' כהסבר הבלעדי להנהגת העולם.","הספר נכתב על ידי משה רבנו במדבר סיני.","הספר מסתיים בכך שאיוב מקלל את אלוהים ומת."],correctAnswer:1,explanation:"למרות ההבדלים ביניהם, כל הפרשנים המודרניים מסכימים שספר איוב יוצא נגד הדוגמה הפשטנית של 'תורת הגמול'. העולם מורכב יותר ממשוואה של חטא=עונש."},{question:"איזו תפיסה מיוצגת על ידי הציטוט 'הֲלֹא יִרְאָתְךָ כִּסְלָתֶךָ, תִּקְוָתְךָ וְתֹם דְּרָכֶיךָ' (בדברי אליפז)?",options:["היראה היא טפשית (כסל) ואין לה תוחלת.","יראת השמיים ותום הלב הם הביטחון (כסלה/תקווה) לכך שהסבל יחלוף והטוב ישוב.","איוב הוא כסיל (טיפש) כי הוא מקווה לחינם.","הדרך היחידה להחזיר את הגלגל לאחור היא לוותר על התקווה."],correctAnswer:1,explanation:"'כסלה' כאן משמעותו 'ביטחון'. אליפז אומר לאיוב: היראה שלך צריכה להיות מקור התקווה והביטחון שלך. אם אתה צדיק, בסוף יהיה טוב. זוהי הבעת אמון מוחלטת בתורת הגמול."},{question:"מה מסמל המספר 'שלוש' בהקשר של רעי איוב (שלושת הרעים)?",options:["את הקדושה והשלמות האלוהית.","את המעבר מיחיד לחברה.","את שלושת חלקי היממה (בוקר, צהריים, ערב).","את חוסר היציבות של הטיעון שלהם."],correctAnswer:1,explanation:"בחומר הלימוד (יחידה 2, שקופיות 24-25) מוסבר כי במצרים העתיקה ובתרבויות הקדום, המספר 3 מסמן ריבוי. שלושת הרעים אינם סתם אנשים פרטיים, אלא מייצגים את החברה והקונצנזוס הדתי מול איוב היחיד."},{question:"מהי טענתו המרכזית של צופר בנאומו הראשון?",options:["לאדם אין יכולת להבין את חכמת האל האינסופית.","איוב סובל בגלל חטאי בניו שנהרגו.","השטן הוא הגורם הישיר לסבלו של איוב.","הסבל הוא מבחן שנועד לחשל את אופיו של האדם."],correctAnswer:0,explanation:"צופר מדגיש את הפער בין ידיעת האדם המוגבלת לחכמת האל ('החקר אלוה תמצא?'). הוא טוען שרק אלוהים יודע את האמת, ולכן אם איוב נענש – יש לכך סיבה, גם אם איוב לא מבין אותה."},{question:"מהי משמעות המונח 'פַּלֵּל' (להתפלל) על פי ההקשר המקראי שהובא בכיתה?",options:["בקשת רחמים ותחנונים.","פעולה משפטית של עתירה.","טקס של הקרבת קורבנות.","אמירת דברי שבח והודיה."],correctAnswer:1,explanation:"ביחידה 2 (עמ' 28) מוסבר שהשורש פל'ל קשור למשפט (כמו 'נתן בפלילים'). התפילה נתפסת כהגשת עתירה משפטית בפני האל השופט."},{question:"איזו תפיסה מנסה איוב להפריך באמצעות תיאור ה'רשע וטוב לו' (פרק כ'א)?",options:["את הטענה שהעולם נברא במקרה.","את תורת הגמול של הרעים.","את האמונה בהישארות הנפש.","את חשיבות התפילה בציבור."],correctAnswer:1,explanation:"הרעים טוענים שיש קשר ישיר בין חטא לעונש. איוב מביא דוגמאות מן המציאות ('בתיהם שלום מפחד', 'יבלו בטוב ימיהם') כדי להוכיח שתפיסה זו שגויה ושהרשעים פעמים רבות משגשגים."},{question:"מהו הכשל הלוגי ('המעגל הסגור') בטיעוני הרעים כלפי איוב?",options:["הם טוענים שאיוב אינו קיים באמת אלא הוא משל.","הם מסיקים את החטא מתוך העונש.","הם משתמשים בדברי השטן כדי להצדיק את האל.","הם טוענים שהסבל של איוב הוא דמיוני."],correctAnswer:1,explanation:"ביחידה 8 מוסבר שהרעים חייבים לשמר את התיאוריה שלהם (תורת הגמול). מכיוון שהם רואים עונש גדול, הם מניחים בהכרח שקדם לו חטא גדול, גם ללא ראיות ('הלא רעתך רבה')."},{question:"כיצד מתאר מתתיהו צבת את תופעת הגשם במדבר ('ארץ לא איש')?",options:["כבזבוז משאבים המעיד על חוסר תכנון.","כהוכחה לכך שהעולם לא נועד לשרת את האדם.","כנס שנועד להציל עוברי אורח אבודים.","כעונש לאדם שלא עיבד את האדמה כראוי."],correctAnswer:1,explanation:"צבת טוען שהעולם הוא 'חוץ-חברתי'. העובדה שיורד גשם במקום שאין בו בני אדם מוכיחה שמטרת הטבע אינה תועלתנית עבור האדם, ולכן גם המוסר האנושי לא חל עליו."},{question:"מה מסמלת 'היענה' בנאום ה' מן הסערה על פי צבת?",options:["אכזריות וחוסר היגיון הטבועים בטבע.","טיפשות שדינה להיכחד מן העולם.","אימהית למופת הדואגת לצאצאיה.","סמל לצדיק הנרדף על לא עוול בכפו."],correctAnswer:0,explanation:"היענה מתוארת כמי שמקשיחה ליבה נגד בניה ('הקשיח בניה ללא לה') ושוכחת שהרגל תמעך את ביציה. זה מדגים עולם שיש בו אלמנטים 'פגומים' מוסרית או אדישים."},{question:"מהי מטרת השאלות הרטוריות ('איפה היית ביוסדי ארץ') לפי גישת גרינשטיין?",options:["לעורר את סקרנותו של איוב ללמוד מדעים.","לפסול את איוב מלהעיד במשפט.","לגרום לאיוב להרגיש אהוב ורצוי.","לבדוק את הידע הגיאוגרפי של איוב."],correctAnswer:1,explanation:"גרינשטיין רואה בנאום מהלך משפטי (פורנזי). השאלות נועדו להראות שאיוב לא היה נוכח בבריאה, ולכן עדותו היא 'עדות שמיעה' שאינה קבילה, מה שמוביל לדחיית התביעה שלו."},{question:"מהי משמעות המילה 'עצה' בפרשנותו של מייקל פוקס?",options:["המלצה בלתי מחייבת להתנהגות טובה.","תוכנית וסדר אלוהי (Design).","עצה רעה שנתן השטן לאלוהים.","סוד כמוס שאסור לאדם לדעת."],correctAnswer:1,explanation:"פוקס מדגיש את המילים 'מי זה מחשיך עצה'. ה'עצה' היא התוכנית וההרמוניה של הבריאה. אלוהים מראה לאיוב שיש סדר בעולם, גם אם הסדר הזה אינו מבוסס על שכר ועונש (גמול)."},{question:"מהי 'נקודת התורפה' בתיאוריה של צבת (העולם הא-מוסרי)?",options:["תיאור השחר המנער רשעים.","תיאור הלוויתן המשחק בים.","העובדה שאיוב מקבל את רכושו בחזרה.","חוסר ההתייחסות לדמות השטן."],correctAnswer:0,explanation:"צבת טוען שהטבע אדיש למוסר, אך בנאום האל (ל'ח) נאמר שהשחר 'אוחז בכנפות הארץ וינערו רשעים ממנה'. פסוק זה קושר בין תופעת טבע לבין פעולה מוסרית, וזה סותר את התיאוריה."},{question:"מדוע משתמש איוב בדימוי של 'עבד שואף צל' (בפרק ז')?",options:["כדי לתאר את תשוקתו ללמוד תורה בצל החכמה.","כדי להמחיש את כמיהתו למוות ולמנוחה מסבלו.","כדי להראות שהוא עבד נאמן לאלוהים בכל מצב.","כדי להתלונן על החום הכבד במדבר בו הוא יושב."],correctAnswer:1,explanation:"איוב משווה את חייו לחיי עבד שעובד בפרך ומחכה לערב ('צל') ולסוף יום העבודה, כלומר למוות שיגאל אותו מהייסורים (יחידה 3)."},{question:"עמדתו של מי מהדוברים משתקפת בפסוק 'הֵן יִרְאַת אֲדֹנָי הִיא חָכְמָה וְסוּר מֵרָע בִּינָה'?",options:["איוב","אלוהים","הרעים","אליהוא"],correctAnswer:2,explanation:"הפסוק מציג את 'החכמה המעשית' (יראת ה') כתחליף היחיד הנגיש לאדם, בעוד החכמה האלוהית נשגבת ממנו. גישה זו תואמת את עמדת הרעים הדורשת מהאדם ציות וכניעה."},{question:"מהי הפונקציה של 'נאומי הסיכום' של איוב (פרקים כ'ט-ל'א)?",options:["לבקש סליחה מהרעים על דבריו הקשים.","להציב את המציאות (החוויה האישית) מול התיאוריה.","לסכם את הנכסים שנשארו לו לצורך צוואה.","להודות שצדקו הרעים והוא אכן חטא."],correctAnswer:1,explanation:"איוב מציג את עברו המפואר (פרק כ'ט) ואת ההווה הנורא (פרק ל') כראיה אמפירית לכך שהוא קיים את כל כללי החכמה אך קיבל עונש במקום שכר, ובכך מפריך את תורת הגמול."},{question:"לפי קרול ניוסם, כיצד משפיע תיאור המפלצות (בהמות ולוויתן) על איוב?",options:["הוא מפחיד אותו עד כדי חזרה בתשובה.","הוא יוצר חוויה של 'הנשגב הטראגי'.","הוא גורם לו להבין שהוא יכול לצוד אותן.","הוא משכנע אותו שהעולם הוא מקום בטוח."],correctAnswer:1,explanation:"ניוסם טוענת שהמפגש עם הכוחות הכאוטיים והאדירים (הנשגב) משנה את התודעה של איוב. הוא לא מקבל תשובה לוגית, אלא חווה את אפסותו מול גודל הבריאה, מה שמביא לשקט נפשי (קתרזיס)."},{question:"מהי תגובתו של איוב לטענת 'הגמול המושהה' (שאלוהים ישלם לצאצאיו)?",options:["הוא מקבל זאת כנחמה מספקת להמשך השושלת.","הוא טוען שזה לא הוגן ('לא צדק') שהאדם המת לא יודע מה קורה לבניו.","הוא שמח שבניו לפחות יזכו לחיים טובים יותר ממנו.","הוא מבקש שכר כספי מיידי במקום הבטחות לעתיד."],correctAnswer:1,explanation:"איוב דוחה את רעיון הגמול המושהה (פרק כ'א). הוא טוען 'יִכְלוּ בַהֶבֶל יְמֵיהֶם', כלומר, אם הרשע מת בשלווה, לא אכפת לו מה יקרה לילדיו אחריו ('כי מה חפצו בביתו אחריו'), ולכן אין בכך עונש אמיתי."},{question:"מהי הביקורת המרכזית של איוב על רעיו בתשובותיו?",options:["שהם לא הביאו לו אוכל ותרופות כשהוא חולה.","חכמתם בנאלית ולא מועילה והם תומכים בעמדתו של האל מתוך פחד במקום לעמוד לצדו של חברם הסובל.","שהם לא מתפללים עליו חזק מספיק.","שהם למעשה שליחים של השטן שבאו לפתות אותו."],correctAnswer:1,explanation:"איוב מלין על כך שרעיו בגדו בו ושהם נאחזים בקלישאות ('משלי אפר' – בנאליות) מתוך פחד מאלוהים ('הלא שאתו תבעת אתכם'), במקום להעז ולגלות אמפתיה אמיתית."},{question:"מהי המשמעות המשפטית של פנייתו של איוב לשבועה בפרק כ'ז ('חַי אֵל הֵסִיר מִשְׁפָּטִי')?",options:["זוהי טקטיקה משפטית שנועדה לאלץ את האל להגיב, תוך יצירת פרדוקס שבו הוא נשבע באל שפגע בו.","הוא מודה סוף סוף בכל חטאיו בפני הרעים.","הוא מחליט להתאבד כדי להפסיק את הסבל.","הוא מצטרף לדעתם של הרעים ומצדיק אותם."],correctAnswer:0,explanation:"איוב נוקט במהלך פרדוקסלי: הוא נשבע באלוהים (מקור הסמכות) נגד אלוהים (שעשה לו עוול). זהו מהלך שנועד לכפות על הצד השני להתייחס לתביעה."},{question:'מדוע מקפיד המחבר המקראי למקם את איוב ב"ארץ עוץ" ולשייכו ל"בני קדם"?',options:["כדי להדגיש את אופיו האוניברסלי של הדיון ולנתק אותו מהיסטוריה לאומית-ישראלית.","כדי להראות שאיוב היה צאצא ישיר של עשו, ולכן עונשו נובע מעוונות אבותיו.","כדי להוכיח שתורת הגמול קיימת גם בעמים עובדי אלילים ולא רק בעם ישראל.","כדי לרמוז שמדובר בסיפור היסטורי מדויק שהתרחש בתקופת האבות במדבר."],correctAnswer:0,explanation:"הזיהוי של ארץ עוץ ובני קדם נועד ליצור דמות על-זמנית ואוניברסלית, המנותקת מההיסטוריה הישראלית (ללא שיוך לאומי, מועד מוגדר או מצוות התורה), וכך מתאפשר דיון פילוסופי רחב ונקי."},{question:`מהי מהות הטענה שמציג "השטן" בפני אלוהים בפרק א'?`,options:["האדם מטבעו נוטה לרע, ולא ייתכן שאיוב שומר על צדקתו ללא חטאים נסתרים.","אמונתו של איוב היא תוצר של כדאיות ותועלתנות, ולא ביטוי של יראה לשמה.","אלוהים מעלים עין מפשעי העשירים, בעודו מעניש את העניים על חטאים קלים.","איוב מקיים את המצוות רק מתוך פחד מעונש המוות שירחף מעל בניו."],correctAnswer:1,explanation:'השטן (כקטגור) טוען: "החינם ירא איוב אלוהים?". לפי טענה זו, אמונתו של איוב תלויה ברווח ובשפע; אם יילקחו ממנו, תתמוטט היראה.'},{question:'מהי המשמעות הספרותית של מבנה שרשרת האסונות שפוקדים את איוב ("עוד זה מדבר וזה בא")?',options:["להראות שאיוב סבל ממזל רע עקבי לאורך תקופה ארוכה של מספר חודשים.","להדגיש את עמידותו של איוב, שהצליח להתפלל לאחר כל אסון בנפרד.","ליצור תחושה של מתקפה טוטאלית, מתואמת ועל-אנושית שאינה מותירה רגע לנשום.","להמחיש את שיתוף הפעולה בין כוחות הטבע לבין השבטים העוינים באזור."],correctAnswer:2,explanation:'השרשרת הקצבית מייצרת תחושת "בליץ": לא רצף מקרי של פגיעות, אלא מתקפה כוללת שלא מאפשרת לאיוב לעבד את האובדן בין אירוע לאירוע.'},{question:`מה מבקש איוב לעשות ב"קללת היום" שלו בפרק ג'?`,options:["לדרוש מאלוהים שיתגלה אליו ויסביר לו מדוע הוא סובל.","לבקש את מותם של שלושת רעיו שלא השכילו לנחם אותו.","למחוק את יום היוולדו מלוח השנה ולפרק את סדר הבריאה חזרה לתוהו.","לקלל את יום הדין העתידי שבו יישפטו כל בני האדם על חטאיהם."],correctAnswer:2,explanation:"איוב קורא לבטל את יום לידתו ואת לילו, בשפה ההופכת את מעשה בראשית: החזרת חושך וכאוס במקום סדר, אור וחיים."},{question:"מהו ההבדל המרכזי בין יחסו של איוב למוות (בפרק ג') לבין יחסו של קהלת למוות?",options:["איוב רואה במוות עונש על חטאיו, בעוד קהלת רואה בו תהליך ביולוגי טבעי.","איוב מתאר את המוות כמרחב של מנוחה ושוויון, ואילו קהלת רואה בו חידלון ורע מוחלט.","איוב מאמין בתחיית המתים ובשכר בעולם הבא, ואילו קהלת כופר בכך לחלוטין.","איוב פוחד מהשאול ומהחושך, בעוד קהלת מקבל את המוות בשמחה ובהשלמה."],correctAnswer:1,explanation:'איוב מתאר את המוות כמקום שבו "קטון וגדול שם הוא" ויש שקט מן הסבל; קהלת מדגיש את אכזריות החידלון ואת עליונות החיים גם במצב נמוך.'},{question:"כיצד מפרש אליפז בנאומו הראשון את סבלו של איוב?",options:['הסבל הוא כלי חינוכי אלוהי ("מוסר") שנועד לזכך את האדם מחטאיו הקלים.',"הסבל הוא גזירת גורל עיוורת, ועל האדם לקבל אותה ללא ניסיון להבינה.","הסבל הוא עונש ישיר על כך שאיוב התגאה בעושרו בפני עניי העיר.","הסבל הוא אשליה, והאדם המאמין באמת אינו מרגיש כאב פיזי."],correctAnswer:0,explanation:'אליפז מציג מודל של "מוסר": ייסורים כחינוך ותיקון, לאו דווקא כעונש מוחלט על פשע חמור. זה הניסיון הראשון לרכך את תורת הגמול.'},{question:"על מה נשען אליפז כמקור סמכות לדבריו בנאומו הראשון?",options:["על מגילות עתיקות שנכתבו על ידי חכמי קדם בארץ מצרים.","על חזון לילי מיסטי והתגלות רוחנית שהעבירו לו מסר שמיימי.","על חוקי התורה כפי שנמסרו למשה בהר סיני.","על תצפיות מדעיות וחקירת תופעות הטבע בעולם הסובב אותו."],correctAnswer:1,explanation:'אליפז מתאר חוויה מיסטית ("ואלי דבר יגונב") כמקור הסמכות: קול/רוח בלילה שמעבירים לו מסר תיאולוגי על יחס אדם-אל.'},{question:'איזה עיקרון תיאולוגי ממחיש בלדד באמצעות "משל שני העצים"?',options:["האל מעניש את הרשעים בעולם הזה, אך שומר את שכר הצדיקים לעולם הבא.","הצלחת הרשע היא זמנית ותלויה בתנאים חיצוניים, בעוד הצדיק ישרוד ויתחדש.","אין כל הבדל בין צדיק לרשע, שניהם נתונים לחסדי פגעי מזג האוויר.","האדם נדון לסבל מתמשך, בדיוק כפי שהעץ נכרת לבסוף על ידי חוטב העצים."],correctAnswer:1,explanation:"בלדד משתמש בדימוי צמח תלוי-מים כדי להראות שהצלחת הרשע נראית מהירה אך אינה יציבה; בסוף היא קמלה ונעלמת."},{question:"מהי טענתו המרכזית של צופר הנעמתי כלפי איוב?",options:["חכמת אלוהים היא אינסופית ובלתי נתפסת, ולמעשה איוב נענש פחות ממה שמגיע לו.","איוב צריך להפסיק להתפלל, שכן גזר הדין כבר נחתם ולא ניתן לשנותו.","השטן הוא זה שפוגע באיוב, ואלוהים רק ממתין שאיוב יעמוד בניסיון.","על איוב להקריב קורבנות רבים יותר כדי לרצות את האל הזועם."],correctAnswer:0,explanation:'צופר טוען שאיוב כלל לא משיג את עומק החכמה האלוהית, ואם היה משיג היה מבין שעונשו אף הוקל ביחס לעוונו ("ישה לך אלוה מעוונך").'},{question:'מדוע משווה איוב את רעיו ל"נחל אכזב" (כאפיק נחלים יעבורו)?',options:["מכיוון שדבריהם שוצפים ורועשים אך אין בהם דברי חכמה של ממש.","מכיוון שהם נראו כמקור נחמה בטוח, אך נעלמו ואכזבו בדיוק ברגע המשבר.","מכיוון שהם הגיעו אליו במהירות גדולה מרחבי המזרח כדי להשתתף בצערו.","מכיוון שאמונתם באלוהים היא חולפת ומשתנה בהתאם למזג האוויר ולנסיבות."],correctAnswer:1,explanation:'נחל אכזב זורם בעונה הרטובה אך נעלם בשיא הצורך. כך גם הרעים: בזמן שפע היו "יש", וברגע מצוקה התבררו כמקור שלא מספק מים.'},{question:`בפרק ז', איוב משתמש במוטיבים ממזמור ח' בתהילים ("מה אנוש כי תזכרנו"). מהי מטרתו?`,options:["להראות שבדיוק כמו בתהילים, האדם הוא נזר הבריאה וזוכה להשגחה אוהבת.","לבקש מאלוהים שיתן לו כוח לשלוט בחיות הרעות שתוקפות את עדרו.","ליצור פארודיה שבה תשומת הלב האלוהית מתוארת כמעקב אובססיבי ומחניק.","להוכיח לרעיו שהוא מכיר את כתבי הקודש טוב מהם, ולכן הוא צודק בוויכוח."],correctAnswer:2,explanation:"איוב מהפך את לשון מזמור ח' מלשון התפעלות ללשון מחאה: במקום קירבה מיטיבה, ההשגחה נתפסת כרדיפה בלתי פוסקת שאין בה מנוחה."},{question:'מהי תגובתו של איוב למשל העץ של בלדד (בפרק י"ד)?',options:["איוב מסכים עם המשל ומביע תקווה שגם חייו יצמחו מחדש לאחר המשבר.","איוב טוען שלעץ אכן יש מנגנון התחדשות, אך האדם שמת נעלם לבלי שוב.","איוב דוחה את המשל בטענה שעצים אינם סובלים, ולכן ההשוואה אינה תקפה.","איוב משתמש בדימוי העץ כדי להראות שאלוהים עוקר גם את הצדיקים הגדולים ביותר."],correctAnswer:1,explanation:'איוב מאמץ את הדימוי כדי לשלול אותו ביחס לאדם: לעץ יש "תקווה" ביולוגית לצמיחה מחודשת, אך גבר שמת "ואיו".'},{question:' "עֹשֶׂה גְדֹלוֹת וְאֵין חֵקֶר, נִפְלָאוֹת עַד־אֵין מִסְפָּר". אליפז משתמש בפסוק זה, ואיוב חוזר עליו. מה ההבדל במשמעות?',options:["אליפז מתאר את בריאת העולם בעבר, ואיוב מתאר את השגחת האל בהווה.","אליפז מתכוון לאלים הכנעניים, ואילו איוב מתכוון לאלוהי ישראל הבלעדי.","אליפז רואה בכוח האל ביטוי של תיקון וחסד, ואיוב רואה בו ביטוי של כאוס ושרירותיות.","שניהם מסכימים על המשמעות, אך איוב טוען שהפסוק חל רק על המלאכים."],correctAnswer:2,explanation:'אותן מילים מקבלות משמעות הפוכה: אצל אליפז "גדולות" הן חסד ותיקון; אצל איוב אותו כוח בלתי-נחקר מוצג כהורס, מחשיך ומוחץ ללא הבחנה מוסרית.'},{question:'מה כוונת איוב כשהוא אומר "לא יש בינינו מוכיח, ישת ידו על שנינו"?',options:["הוא מתלונן שחבריו מסרבים להוכיח אותו בצורה ישירה וכנה על חטאיו.","הוא טוען שאלוהים מסרב להוכיח אותו ולהסביר לו במה בדיוק פשע.","הוא קובע שאין בינו לבין אלוהים גורם מתווך או בורר שיאפשר משפט הוגן.","הוא מבקש מהנביאים שיתערבו בסכסוך ויוכיחו לרעיו שהם טועים."],correctAnswer:2,explanation:'איוב מצביע על בעיית אי-השוויון המוחלט: ללא בורר ניטרלי אין "הליך הוגן" בין אדם מוגבל לאל כל-יכול.'},{question:"על פי פרק ט', כיצד תופס איוב את היחס האלוהי לצדיק ולרשע בעת אסון?",options:["אלוהים בוחן את הצדיק ומעניש את הרשע, גם אם הדבר נראה זהה כלפי חוץ.",'אלוהים משמיד את שניהם יחד ללא כל הבחנה ("תם ורשע הוא מכלה").',"אלוהים נותן לטבע לפעול את פעולתו, ואינו מתערב כלל בחיי בני האדם.","אלוהים מעניש את הצדיק כדי שיכפר על חטאי הרשעים שחיים סביבו."],correctAnswer:1,explanation:"בנקודת השיא של מחאתו, איוב טוען שהאסון אינו מבחין בין תם לרשע. זו התקפה ישירה על נוסחת הגמול המסורתית."},{question:'מדוע איוב קורא לרעיו "רופאי אליל" בפרק י"ג?',options:["כי הם מציעים לו תרופות עממיות שאינן מועילות לריפוי מחלת השחין שלו.","כי הם משקרים ומעוותים את המציאות רק כדי להגן על התיאולוגיה של אלוהים.","כי הם מתפללים עבורו לאלים זרים, בניגוד לאמונתו המונותיאיסטית.","כי הם טוענים שהמחלה שלו נובעת מכישוף שהוטל עליו על ידי אויביו."],correctAnswer:1,explanation:'איוב מאשים אותם שהם "מרפאים שקר": במקום להתמודד עם המציאות, הם מסלפים אותה כדי להגן על האל בכל מחיר.'},{question:'אילו שני תנאים מוקדמים דורש איוב מאלוהים לפני קיום ה"משפט" ביניהם?',options:["שיחזיר לו את בניו וירפא את מחלתו לחלוטין.","שיסלק את חבריו מן האזור ושירד להתדיין עמו בארץ.","שיסיר ממנו את הכאב הפיזי ושיפסיק להטיל עליו אימה נפשית.","שיודה פומבית בטעותו ושיכתוב את פסק הדין על לוח אבן."],correctAnswer:2,explanation:'בפרק י"ג איוב דורש: "כפך מעלי הרחק" (הסרת הסבל הפיזי) ו"ואימתך אל תבעתני" (הסרת האימה), כדי לאפשר התדיינות אמיתית.'},{question:'בנאומו השלישי (פרק כ"ב), אליפז מאשים את איוב בגזל, הפשטת ערומים ופגיעה באלמנות. מה המניע התיאולוגי להאשמות אלו?',options:["אליפז קיבל מידע חדש מהשיירות שעברו באזור על עברו הפלילי של איוב.","איוב התוודה על חטאים אלו בשיחות אישיות עם אליפז לפני פרוץ האסונות.",'אליפז מבצע "הנדסה לאחור": מכיוון שהעונש כה כבד, הוא חייב להמציא חטא כבד כדי לשמר את תורת הגמול.',"אליפז מנסה לעורר את זעמו של איוב כדי שזה יפסיק לשתוק ויתחיל להתגונן."],correctAnswer:2,explanation:"זהו מנגנון של שמירת התיאוריה: אם העונש עצום, מוכרח שהיה חטא עצום. לכן ההאשמות נבנות בדיעבד כדי למנוע קריסה של תורת הגמול."},{question:'מהו הפתרון שמציע אליפז לאיוב בסוף נאומו השלישי ("הסכן נא עמו ושלם")?',options:["התאבדות מתוך השלמה, כדי להפסיק את ייסוריו בעולם הזה.","התפייסות וחזרה בתשובה לאל, שיבטיחו לו שגשוג ועושר חומרי מחודש.","עזיבת ארץ עוץ ומעבר למקום שבו לא מכירים אותו ואת קלונו.","תרומת כל רכושו הנותר לעניים כדי לכפר על עושק האלמנות."],correctAnswer:1,explanation:"אליפז מציע מודל תועלתני קלאסי: חזור בתשובה, התפייס עם האל, ותקבל בחזרה שגשוג חומרי וביטחון."},{question:'מהי מטרתה של "שבועת הניקוי" (פרק ל"א) באסטרטגיה של איוב מול אלוהים?',options:["לסיים את הוויכוח עם הרעים על ידי השבעתם שלא לדבר אליו יותר.","לטהר את שמו בפני הקהילה המקומית כדי שיוכל לחזור לכהן כשופט.",'ליצור "מלכוד משפטי": אם לא יענש מיד על השבועה, שתיקת האל תיחשב כהודאה בחפותו של איוב.',"לחזור בתשובה באופן פומבי ולקבל על עצמו קוד אתי חדש ומחמיר."],correctAnswer:2,explanation:"איוב מציב את השבועה ככלי הכרעה משפטי: שקר אמור לגרור עונש מיידי; היעדר תגובה אלוהית מתפקד כאישור לטענת חפותו."},{question:'איזה מהנושאים הבאים אינו נכלל ב"רשימת המכולת המוסרית" של איוב בשבועתו בפרק ל"א?',options:["פגיעה בזכויות העבדים והאמהות שלו.","שמחה לאיד בנפול אויביו.","חילול שבת ומועדי ישראל.","עבודה זרה בסתר (נשיקת היד לאור השמש)."],correctAnswer:2,explanation:"איוב מונה חטאים מוסריים אוניברסליים (צדק חברתי, טוהר, איסור עבודה זרה), אך לא מצוות פולחניות-לאומיות כמו שבת ומועדים."},{question:'כיצד מתאר איוב את עברו (פרק כ"ט) ביחס לתורת החכמה?',options:["כעבר שבו חי בחטא ובהוללות, אך מעולם לא נתפס על ידי החברה.","כהתגלמות האידיאל של חכם ושופט צדק, שזכה לשפע ולכבוד מהחברה והאל.","כחיים של עוני ומחסור, שרק בזכות תפילותיו הפכו לחיים של עושר.","כתקופה שבה חיפש את אלוהים במדבר ולא מצא תשובות."],correctAnswer:1,explanation:"איוב מתאר את עצמו כדמות מופת ציבורית: לא רק אדם פרטי מוסרי, אלא גם שופט ומנהיג חברתי שקיבל הכרה וכבוד."},{question:"אלוהים מתגלה מן הסערה, אך עונה לאיוב בסדרה ארוכה של תיאורי טבע. מהי ההסכמה הגורפת של רוב החוקרים המודרניים לגבי משמעות המענה?",options:['אלוהים מאשר לחלוטין את "תורת הגמול" ומוכיח שאיוב חטא.',"המענה מוכיח שהשטן היה אחראי לכל, ואלוהים מתנצל על חוסר התערבותו.","המענה מסביר באופן הגיוני מדוע סבלו של צדיק נחוץ למען קיום העולם.",'המענה דוחה את עקרון "מידה כנגד מידה" ומסיט את הדיון מהמישור המוסרי למישור הקוסמי.'],correctAnswer:3,explanation:"הקונצנזוס המחקרי מדגיש הסטת מוקד: במקום משפט שכר-ועונש אנושי, מוצג יקום רחב, פראי ונשגב שאינו כפוף לנוסחת גמול פשוטה."},{question:"בספר איוב מוזכרים בעלי חיים כמו היענה ופרא המדבר. מה הם נועדו להמחיש לפי הגישות המחקריות המודרניות?",options:["את חשיבותו של האדם שקיבל את השליטה המלאה על כל החיות הללו.","את העובדה שהעולם נברא כדי לספק לאדם מזון וביגוד בצורות שונות.","את קיומו של עולם פראי שאינו סובב סביב האדם, צרכיו, או חוקי המוסר שלו.","את העובדה שהחטא של האדם השחית גם את עולם החי והפך אותו לאכזרי."],correctAnswer:2,explanation:"החיות מצביעות על עולם לא-אנתרופוצנטרי: יש מציאות חיה, פראית ואוטונומית שאינה נמדדת לפי תועלת לאדם או לפי מוסר אנושי."},{question:`בפרקים מ'-מ"א, אלוהים מתאר בהרחבה את ה"בהמות" וה"לוויתן". מהו המסר העולה מתיאור זה?`,options:["המפלצות הללו מייצגות את העונש שמחכה לאיוב אם לא יחזור בתשובה מיידית.","אלוהים מתגאה ביצירות הכאוטיות והפראיות שלו, ואינו רואה בהן משהו שיש להשמיד או לביית.","אלוהים מודה שאין לו שליטה מלאה על כוחות הרוע בעולם, ולכן האדם סובל.","המפלצות הן הוכחה לכך שבעבר העולם היה עשוי ממים בלבד, לפני ימי הבריאה."],correctAnswer:1,explanation:"בהמות ולוויתן מתוארים כהדר הבריאה, לא כתקלה שיש לתקן. המסר הוא שהכאוטי והפראי הם חלק לגיטימי מן הסדר האלוהי."},{question:'מהו ה"סוף המטריד" (האפילוג) של ספר איוב מבחינה תיאולוגית וספרותית?',options:["איוב מת בסבלו ללא כל תשובה, והרעים מוכרזים כצדיקים על ידי אלוהים.","השטן מופיע שוב ודורש סיבוב שלישי של ניסיונות, מה שמותיר את הסיפור פתוח.","אלוהים גולה את איוב מארץ עוץ, והוא נאלץ לנדוד עד סוף ימיו.","איוב מקבל את רכושו ובניו בכפליים, מה שלכאורה מחזיר ומאשרר את תורת הגמול שאותה הספר ניסה לסתור."],correctAnswer:3,explanation:'האפילוג משיב שכר חומרי כפול ומייצר מתח חריף מול הדיון הפואטי הארוך שערער את משוואת הגמול הפשוטה. זו הסיבה לכינויו "סוף מטריד".'},{question:"בתיאור שיקום משפחתו של איוב באפילוג, מופיע פרט ייחודי ויוצא דופן בחוק המקראי. מהו?",options:["בנותיו של איוב מקבלות שמות מפורטים ויורשות נחלה יחד עם אחיהן.","בניו של איוב מסרבים לקחת חלק ברכוש ומחליטים להקדיש את חייהם למקדש.",'אשתו של איוב מתנצלת בפומבי על כך שאמרה לו "ברך אלוהים ומת".',"איוב מאמץ את ילדי חבריו לאחר שאלוהים מעניש את הרעים במוות."],correctAnswer:0,explanation:"האפילוג מדגיש שבנות איוב נקובות בשם וגם מקבלות נחלה לצד אחיהן, פרט נדיר וחריג במרחב החוקי-חברתי המקראי."},{question:'מהי התרומה הספרותית המרכזית של מיקום העלילה ב"ארץ עוץ" ושיוכו של איוב ל"בני קדם"?',options:["חיזוק הקשר ההיסטורי לעם ישראל ולמסורות האבות הקדומים.","יצירת עמימות המעניקה לסיפור נופך אוניברסלי וכלל-אנושי.","הדגשת הניגוד בין חכמת המזרח העתיק לבין חכמת התורה.","מתן הסבר גיאוגרפי ריאליסטי למקורות העושר העצום שלו."],correctAnswer:1,explanation:'המסגור ב"ארץ עוץ" ו"בני קדם" מרחיק את הסיפור מהקשר לאומי-ישראלי נקודתי ומעניק לו אופי אוניברסלי.'},{question:`כיצד מתואר "השטן" בסיפור המסגרת של ספר איוב (פרקים א'-ב')?`,options:["כישות דמונית עצמאית הנאבקת באלוהים על השליטה בעולם.","כנציג עמי הקדם המנסה לערער את ביטחונו של אדם צדיק.","כתפקיד של קטגור בבית הדין השמיימי, הפועל ברשות האל.","כהאנשה של היצר הרע הקיים בתוך לבו של איוב עצמו."],correctAnswer:2,explanation:"בספר איוב השטן מתפקד כקטגור הפועל במסגרת הסמכות האלוהית, ולא ככוח עצמאי שמורד באל."},{question:'מהי טענתו המרכזית של השטן ("החינם ירא איוב אלוהים") כנגד צדקתו של איוב?',options:["איוב מקפיד על מצוות חיצוניות אך בתוכו הוא חוטא בסתר.","צדקתו של איוב אינה כנה אלא מבוססת על אינטרס ותועלת.","איוב צדיק רק בזכות הקורבנות הרבים שהוא מקריב עבור בניו.","יראת השמים של איוב מבוססת על פחד מעונש ולא על אהבה."],correctAnswer:1,explanation:'טענת "החינם" מציגה את יראת איוב כמותנית ברווח אישי, ולכן לא כמוסר טהור אלא כאינטרס.'},{question:'מדוע מבקש השטן לפגוע בגופו של איוב בסיבוב השני ("עור בעד עור")?',options:["כי אובדן רכוש וילדים עדיין לא בוחן את ההישרדות האישית.","כי הכאב הפיזי החריף יגרום לאיוב לאבד את שפיות דעתו.","כי אלוהים אסר עליו לפגוע בנפשו של איוב באופן מיידי וישיר.","כי השחין נחשב בעולם הקדום כעונש השמור רק לחטאים חמורים."],correctAnswer:0,explanation:'לפי הטענה "עור בעד עור", האדם יוותר על הכול כדי להציל את עצמו, ולכן הפגיעה בגוף היא מבחן קיצוני יותר.'},{question:'על פי הנלמד בקורס, מה מייצגת אשת איוב באמירתה "ברך אלוהים ומת"?',options:["את החולשה של האמונה בבית איוב ביחס לאמונתו האיתנה של הגבר.","את שליחתו של השטן עלי אדמות, שתפקידה היחיד להכשיל את הצדיק.","את קולו של האדם הסביר והפרגמטי מול ייסורי חינם חסרי פשר.","את ההוכחה הניצחת לכך שמשפחתו של איוב אכן חטאה מראש בסתר."],correctAnswer:2,explanation:"בקורס היא מוצגת כקול אנושי-פרגמטי שמגיב לחוסר ההיגיון שבייסורים ולא כדמות שטנית."},{question:"איזה מהלך מתרחש בפרק ג', כאשר איוב שובר את שתיקתו הממושכת?",options:["איוב פותח בבקשת סליחה וכפרה על חטאים שאולי חטא בהם בשוגג.","איוב פונה אל רעיו ודורש מהם שיסבירו לו את פשר ייסוריו הקשים.","איוב תוקף ישירות את אלוהים על חוסר הצדק שנעשה לכל בני משפחתו.","איוב מבקש לקלל ולבטל את עצם הבריאה ואת קיומו של יום לידתו."],correctAnswer:3,explanation:"נאום הפתיחה של איוב הוא קללת היום והלילה של לידתו, מהלך שמערער את עצם ההוויה ולא רק מבקש הסבר נקודתי."},{question:`מהי המשמעות המיתולוגית של קריאת איוב "העתידים עורר לויתן" (איוב ג')?`,options:["הבעת משאלה שכוחות הכאוס הקדמונים יחזרו ויפרקו את סדר הבריאה.","קריאה לכוחות השמימיים שיבואו לשפוט את אלוהים על מעשיו האכזריים.","בקשה מחיות הים העצומות לבלוע אותו כדי לסיים את חייו המרים והקשים.","אמונה כי רק נס קוסמי אדיר ממדים יוכל אי פעם לרפא אותו ממחלתו."],correctAnswer:0,explanation:"הקריאה ללויתן מבטאת זימון סמלי של כוחות הכאוס כדי להחזיר את המציאות אל טרום-הסדר."},{question:"כיצד תופס איוב את השאול (המוות) בנאומו הראשון, בניגוד מוחלט לקהלת?",options:["כמקום של אפלה מוחלטת וקרה שבו האדם מאבד לעד את כל זיכרונותיו.","כמרחב אוטופי ומושלם של שוויון, מנוחה שקטה, ושחרור מוחלט מעול המדכאים.","כמחוז של חידלון ואובדן משמעות, מצב גרוע שעדיף להימנע ממנו לחלוטין.","כתחנת מעבר זמנית וקצרה לקראת תחיית המתים והמשפט האלוהי האחרון."],correctAnswer:1,explanation:"בפרק ג' איוב מתאר את השאול כמקום מנוחה ושוויון מן הסבל, בניגוד לקהלת שמדגיש את עדיפות החיים."},{question:"מה ניתן ללמוד מהעובדה שלאיוב מגיעים שלושה רעים, ולא רע אחד (כמו ביצירות המזרח הקדום)?",options:["השלושה מאפשרים לאיוב לנהל דיון פילוסופי מורכב, ארוך ומרובה דעות שונות.","המספר שלושה נועד להעיד על עוצמת עושרו, השפעתו ומעמדו החברתי של איוב.","הרעים אינם רק אנשים פרטיים, אלא מייצגים את הקונצנזוס החברתי והמסורת.","לכל אחד משלושת הרעים יש פתרון תיאולוגי הפוך ומנוגד לחלוטין מזה של חבריו."],correctAnswer:2,explanation:"שלושת הרעים מסמלים את קול החברה והמסורת, ולא רק חברות פרטית של אדם אחד מול איוב."},{question:"מהי גישתו המרכזית של אליפז התימני בנוגע לסיבת הסבל של איוב?",options:["אלוהים מביא ייסורים על האדם ככלי חינוכי של אהבה כדי להשיבו לדרך המוטב.","הסבל האנושי הוא גזירת גורל שרירותית לחלוטין שאין לאדם שום יכולת להבינה.","איוב בוודאי ביצע פשעים מוסריים כבדים ומוסתרים מאוד המצדיקים עונש כה חמור.","הייסורים הם מבחן זמני בלבד שנועד לזכות את איוב בגמול כפול ועצום בעתידו."],correctAnswer:0,explanation:'אליפז מציג את הסבל כ"מוסר" אלוהי מחנך, ולא כשרירות או כגמול עתידי בלבד.'},{question:"על מה מבסס אליפז את סמכותו התיאולוגית בנאומו הראשון?",options:["על מסורות אבות עתיקות ועל חכמתם של דורות קודמים שהועברה אליו בעל פה.","על ניסיונו האישי והכואב כאדם עשיר שחווה בעבר אסון משפחתי דומה והשתקם.","על ניתוח הגיוני ולוגי של חוקי הטבע, מחזוריות הצומח והחיים בעולם החומרי.","על התגלות מיסטית חשאית של רוח וקול שחווה בעצמו במהלך חזיונות הלילה."],correctAnswer:3,explanation:'בנאומו הראשון אליפז נסמך על חוויה מיסטית לילית ("ואלי דבר יגונב") כמקור סמכות לדבריו.'},{question:'מהו "הגמול המושהה" שמציע בלדד השוחי כהסבר למצבו של איוב?',options:["העונש של הרשעים נדחה לעולם הבא, ולכן הם נראים כמשגשגים ומצליחים בהווה.","הצדק יגיע בהמשך, כך שהסבל ההתחלתי והזמני יוביל בסופו של דבר לשגשוג גדול.","האל בוחר להשהות את תגובתו הקשה כדי לאפשר לאדם מספיק זמן לחזור בתשובה.","איוב למעשה נענש כעת על עבירות וחטאים רבים שנדחו והצטברו מתקופת נעוריו."],correctAnswer:1,explanation:"בלדד טוען למבנה של תגמול נדחה: סבל זמני לצדיק כשלב מקדים לשיקום ולשגשוג עתידי."},{question:'כיצד מגיב איוב למשל "שני העצים" (הגומא לעומת העץ הרענן) של בלדד?',options:["הוא מבהיר שאדם אינו עץ, וכאשר אדם מת אין לו שום תקווה להצמיח ענפים ולחיות.","הוא קובע שבמציאות הארצית הרשעים פורחים כעץ רענן, ודווקא האדם הצדיק מתייבש.","הוא מסכים שהרשעים יתייבשו וייעלמו, אך עומד על כך שהוא עצמו איננו אדם רשע.","הוא מזכיר שגם עצים חזקים ושורשיים עלולים להישרף באש אלוהים שיורדת מהשמיים."],correctAnswer:0,explanation:"איוב הופך את המשל ומדגיש שלעץ יש אפשרות התחדשות, אך לאדם שמת אין תקווה ביולוגית לחזרה לחיים."},{question:"מהי עמדתו הקיצונית של צופר הנעמתי כלפי מצבו של איוב?",options:["צופר מודה בגילוי לב שלראשונה הוא נתקל במקרה שבו אין הסבר מוסרי לסבל אנושי.","אלוהים מעניש את איוב ללא סיבה נראית לעין, רק כדי לנסות את רמת סבלנותו ואמונתו.","איוב סובל אך ורק בגלל חטאי בניו המנוחים, ואין לו שום אפשרות לשנות את גזר הדין.","על איוב לשתוק ולהודות, שכן אלוהים למעשה הקל בעונשו ביחס לחטאיו האמיתיים."],correctAnswer:3,explanation:"צופר טוען שאיוב נענש פחות ממה שמגיע לו, ולכן עליו להפסיק להתלונן ולהכיר בכך."},{question:'מה הנמשל ב"משל הנחל האכזב" ("אחי בגדו כמו נחל") שאומר איוב לרעיו?',options:["חבריו היו בטוחים וחזקים בימי עושרו המופלגים, אך קרסו כלכלית יחד איתו כשאיבד הכול.","עצות הרעים שוטפות באגרסיביות רבה כמו שיטפון חורפי, וגורמות לאיוב נזק נפשי נוסף.","חבריו נראו מבטיחים ויציבים מרחוק, אך ברגע המשבר האמיתי הם אכזבו ולא העניקו חסד.","תורת הגמול של הרעים מבוססת כולה על אשליה, ממש כמו מים שמתאדים במהירות בשמש."],correctAnswer:2,explanation:"כמו נחל עונתי שמתייבש כשבאמת זקוקים לו, כך גם הרעים הכזיבו את איוב דווקא בשעת מצוקתו."},{question:`מהי הטענה המרכזית בפרודיה של איוב על תהילים ח' ("מה אנוש כי תגדלנו")?`,options:["האדם אינו ראוי לכבוד והדר, ולכן אלוהים צריך להעביר את השלטון בעולם לידי המלאכים.","השגחת האל אינה חסד כמתואר בתהילים, אלא מעקב אובססיבי וחונק כלפי יצור קטן וזניח.","בניגוד לתהילים, איוב מוכיח שהאדם כלל לא נברא בצלם אלוהים אלא עשוי מחומר ועפר.","אלוהים שכח לחלוטין מן האנושות הסובלת, ולכן העולם מתנהל בכאוס מוחלט ובחוסר צדק."],correctAnswer:1,explanation:"איוב מהפך את מזמור ח' כך שההשגחה נתפסת כרדיפה חונקת ולא כיחס מיטיב ומרומם לאדם."},{question:'לשם מה משתמש איוב במושגים הקוסמיים כגון "הים אני אם תנין כי תשים עלי משמר"?',options:["כדי לרמוז שאלוהים איבד את שליטתו הבלעדית בעולם, והמפלצות העתיקות שוב שולטות בו.","כדי להוכיח ביהירות לרעיו שהוא בקיא במיתולוגיה של המזרח הקדום בדיוק באותה המידה.","כדי לבקש מהאל שיעניק לו כוח להיאבק ברשעים כשם שהאל בעצמו נאבק בהצלחה בתנינים.","כדי להדגיש בצורה אירונית שהוא יצור חלש שאינו מהווה איום המצריך השגחה כה נוקשה."],correctAnswer:3,explanation:'הדימוי האירוני מדגיש את חוסר הפרופורציה בין עוצמת האל לבין האדם החלש שנמצא תחת "משמר" מתמיד.'},{question:"במענה לאליפז (פרק ז'), כיצד מתאר איוב את מהות החיים האנושיים?",options:["כשירות צבאי כפוי, קשה ומעיק, או כעבודת פרך מתמשכת של שכיר יום חסר שכר או תקווה.","כזמן קצר ומוגבל המיועד בעיקר לצבירת זכויות ומצוות לקראת החיים הנצחיים בעולם הבא.","כמסע רוחני מתמיד של לימוד, הזדככות פנימית, התגברות על יצרים והתקרבות איטית לבורא.","כמבחן אלוהי עליון שנועד לבחון ולחזק את הרצון החופשי ואת יכולת הבחירה של בני האדם."],correctAnswer:0,explanation:"איוב מתאר את חיי האדם כעבודת כפייה מתישה של שכיר/חייל, ללא מנוחה וללא אופק ממשי."},{question:"כיצד הופך איוב את משמעות תיאורי העוצמה האלוהית בטבע (רעידות אדמה, הזזת הרים) בפרק ט'?",options:["הוא משתמש בהם כדי להראות שאלוהים פועל בשרירותיות הרסנית, וסותר את טענת הסדר המוסרי.","הוא טוען שאסונות הטבע החמורים הם ההוכחה לכך שגם אלוהים אינו שולט בכוחות הכאוס.","הוא מודה שכוחו של האל אכן מחייב את האדם לשתוק ולקבל את כל הדין בהכנעה מוחלטת.","הוא מוכיח שהטבע פועל בצורה עיוורת לחלוטין ולכן אין שום טעם לחפש סיבה מוסרית לסבל."],correctAnswer:0,explanation:"בפרק ט' איוב מגייס את תיאורי העוצמה כדי להראות שכוח אלוהי עצום אינו שקול בהכרח לצדק מוסרי."},{question:"מדוע איוב מרגיש שאין לו שום סיכוי להצדק במשפט מול אלוהים (פרק ט')?",options:["כי הוא מודה שלמרות השתדלותו העצומה, ייתכן שהוא באמת חטא בחטאים נסתרים מן העין.","כי אלוהים מסרב באופן גורף לשמוע בני אדם ומתקשר עמם אך ורק דרך חזיונות או חלומות.","כי פערי הכוחות הם כה עצומים עד שהאל יעוות את דבריו ויגרום לצדיק להיראות כרשע אשם.","כי השטן ממשיך לקטרג עליו ללא הפסקה בבית הדין השמיימי ומונע ממנו לטעון את טענותיו."],correctAnswer:2,explanation:"תחושת איוב היא של אי-שוויון מוחלט בהליך: מול כוח אינסופי אין לו אפשרות אמיתית להציג צדקתו."},{question:`מהי דרישתו של איוב כשהוא מייחל ל"מוכיח" בפרק ט'?`,options:["הוא מחפש דמות בורר מתווכת, אובייקטיבית וחזקה שתוכל לאזן את פערי הכוחות במשפט.","הוא דורש הוכחה חותכת, ברורה ומיידית מצד אלוהים לפשעים החמורים שבגללם הוא נענש.","הוא מתפלל להתגלות נדירה של נביא זעם שיוכיח את חבריו על צביעותם וחוסר הבנתם.","הוא מבקש שחבריו יפסיקו סוף סוף להטיף לו ויתחילו לשמש כעורכי דינו המסורים מול האל."],correctAnswer:0,explanation:'ה"מוכיח" הוא בורר ניטרלי שאמור לגשר בין שני צדדים לא שווים ולאפשר משפט הוגן.'},{question:`בפרק י', כיצד משתמש איוב בדימוי ה"יוצר והיצירה" (כחומר עשיתני... כחלב תתיכני)?`,options:["כדי להביע הכנעה מוחלטת: כשם שהקדר רשאי לשבור את הכלי, כך האל יכול לעשות בו כרצונו.","כדי להוכיח שהגוף האנושי הוא פלא יצירה מורכב המעיד על חכמתו הבלתי נתפסת של הבורא.","כדי לשאול מדוע האל השקיע כל כך הרבה תשומת לב ביצירתו, רק כדי להרוס אותה באכזריות.","כדי לרמוז בחוצפה שאלוהים יצר אותו מראש כאדם פגום, ולכן אין שום טעם להאשים אותו."],correctAnswer:2,explanation:"איוב מבליט את הסתירה בין השקעת היוצר בבניית החיים לבין ההרס שבא לאחר מכן."},{question:'מה כוונת איוב באמירתו לרעיו: "אמנם כי אתם עם ועמכם תמות חכמה"?',options:["איוב סוף סוף מכיר בחכמתם יוצאת הדופן של חבריו ומודה שאין לו תשובה הולמת לטענותיהם.","איוב קובע בנחרצות שהחכמה האמיתית קיימת רק בישראל ולא אצל רעיו המגיעים מארצות זרות.","איוב מזהיר אותם שאם ימשיכו להחזיק בדעתם השגויה, הם ייענשו במוות כמו שאר הרשעים.","איוב למעשה לועג להם וטוען בבוז שהידע התיאולוגי שהם מציגים הוא בנאלי וידוע לכל אדם."],correctAnswer:3,explanation:"זהו משפט אירוני-לגלגני: איוב מציג את דבריהם כקלישאות שחוקות ולא כחכמה עמוקה וייחודית."},{question:'מדוע איוב מכנה את רעיו "רופאי אליל"?',options:["כי הם מנסים לרפא אותו מן השחין באמצעות כישופים ומסורות זרות במקום לפנות לתפילה.","כי הם ממציאים שקרים תיאולוגיים רק כדי להגן על האל, ובכך בוגדים באמת ובאדם הסובל.","כי הם מתעלמים לחלוטין מהפצעים הפיזיים המדממים שלו ומציעים לו רק ריפוי רוחני מופשט.","כי הם טוענים בטעות שהמחלה שלו נובעת מזיהום טבעי, ואינם מכירים במקורה האלוהי הברור."],correctAnswer:1,explanation:'הכינוי מבטא ביקורת על "ריפוי שקר": הגנה תיאולוגית על האל במחיר עיוות המציאות.'},{question:'לקראת העימות הישיר מול האל, איוב מציב שני תנאים למשפט הוגן (פרק י"ג). מהם?',options:["שאלוהים יסיר ממנו את הכאב הפיזי המשתק, ויבטל את אימתו העצומה כדי לאפשר דיבור.","שחבריו ישמשו במשפט כשופטים אובייקטיביים, ושההליך כולו ייערך לאור יום ולעיני כול.","שאלוהים יודה מראש ובפומבי שטעה בבחירתו, ויבטל לאלתר את ההתערבות עם השטן.","שאלוהים ישיב לו קודם את בניו בריאים, ושיבטיח לו פיצוי כלכלי מלא על כל הסבל שעבר."],correctAnswer:0,explanation:'איוב דורש הסרת הכאב ("כפך מעלי הרחק") והפסקת האימה ("ואימתך אל תבעתני") כתנאי לדיון.'},{question:'איוב תובע מהאל את פתיחת "התיק הפלילי" שלו באומרו "כמה לי עוונות וחטאות". מה עומד מאחורי דרישה זו?',options:["הוא מנסה להתמקח בזהירות על כמות החטאים הידועה כדי להפחית את עוצמת העונש שיקבל.","הוא מבקש וידוי רשמי ופירוט ראיות מדויק, כהתרסה חריפה כנגד ענישה אלוהית עמומה ושרירותית.","הוא מוכיח את רעיו שהם אינם יודעים את המספר המדויק של החטאים, בניגוד גמור לאל עצמו.","הוא מצהיר שהוא מוכן לקחת אחריות גם על חטאים ששכח, ובלבד שיזכה בסופו של דבר לרחמים."],correctAnswer:1,explanation:"הדרישה היא להליך משפטי שקוף: פירוט אישומים וראיות במקום ענישה בלתי מוסברת."},{question:'לפי דברי איוב בפרק י"ג ("העלה נידף תערוץ"), מדוע הרדיפה האלוהית איננה הגיונית?',options:["מכיוון שהעולם מלא תמיד ברשעים אמיתיים שראויים הרבה יותר לתשומת הלב המענישה של אלוהים.","מכיוון שאלוהים מתמקד בהווה בלבד ומתעלם לחלוטין מכך שבעבר הרחוק איוב היה הצדיק הגדול ביותר.","מכיוון שהאדם נמשל לצמח, וכשם שצמח נידף ברוח מתחדש בקלות - כך גם האדם לא באמת נפגע קשות.","מכיוון שהאדם הוא יצור חלש וחסר ישע מטבעו, ולכן מלחמתו של אל אדיר נגדו היא חסרת פרופורציה."],correctAnswer:3,explanation:'דימוי "עלה נידף" מדגיש שהאדם שברירי ממילא, ולכן רדיפה בעוצמה אלוהית נתפסת כחסרת יחס ומידה.'},{question:"מהי המטרה המרכזית של העמימות הגיאוגרפית וההיסטורית באקספוזיציה?",options:["להדגיש שאיוב היה חלק מהאבות של עם ישראל בתקופה הקדומה.","ליצור תחושה של סיפור אוניברסלי שאינו מוגבל לזמן או למקום ספציפי.","להוכיח שחכמת המזרח (בני קדם) נעלה על חכמת ישראל באותה עת.","להסתיר את העובדה שאיוב לא האמין באלוהי ישראל אלא באל כללי."],correctAnswer:1,explanation:"העמימות ממקמת את הספר כשיח אוניברסלי על סבל וצדק, ולא כסיפור היסטורי מקומי."},{question:"על פי פשט הכתוב, מה מאפיין את אישיותו של איוב לפני האסון?",options:["הוא היה אדם דתי מאוד שדאג להקריב קורבנות כפרה על חטאי בניו.","הוא היה מנהיג פוליטי בארץ עוץ שנודע בזכות המשפטים הצודקים שערך.","הוא היה חכם פילוסוף שעסק בשאלות של צדק ורשע עוד לפני שסבל.","הוא היה סגפן שהתנזר מעושר חומרי כדי להתקרב לעבודת האלוהים."],correctAnswer:0,explanation:"הפרולוג מדגיש את יראתו ואת מנהגו להקריב עבור בניו, כביטוי לדתיות וזהירות מוסרית."},{question:"מהי הטענה המרכזית של השטן בעימות הראשון בשמיים?",options:["שאיוב חוטא בסתר ורק מראה פנים של צדיק כלפי החברה.","שאין לאדם יכולת בחירה חופשית אם אלוהים מתערב בעולם.","שיראת השמים של איוב היא אינטרסנטית ונובעת מהשפע שקיבל.","שאיוב אינו ראוי לברכה כי הוא אינו שייך לעם הנבחר (בני ישראל)."],correctAnswer:2,explanation:'טענת "החינם ירא איוב אלוהים" מציגה את צדקת איוב כתלויה בתועלת שקיבל.'},{question:"כיצד ניתן לפרש את השימוש במספרים טיפולוגיים (7 בניו, 3 בנותיו) באקספוזיציה?",options:["עדות לכך שמדובר בדיווח היסטורי מדויק שנרשם בזמן אמת.","רמז לכך שהסיפור הוא בעל אופי אגדי ומתאר מצב של שלמות אידיאלית.",'הוכחה לכך שאיוב שמר על מצוות "פרו ורבו" באדיקות יתרה.',"סימן לכך שהאסון של איוב היה עונש על גאווה משפחתית מופרזת."],correctAnswer:1,explanation:"המספרים 7 ו-3 משמשים כאן כקודים ספרותיים של שלמות, לאו דווקא תיעוד היסטורי מדויק."},{question:`בתגובתו הראשונה של איוב לאסונות ("ה' נתן וה' לקח"), מהי תפיסתו לגבי האלוהות?`,options:["אלוהים הוא דיין צדק שמעניש רק את מי שחטא בגלוי או בסתר.","האדם הוא בעל רכושו, ואלוהים פגע בזכויות הקניין של איוב שלא בצדק.","אלוהים הוא ריבון מוחלט על העולם, וזכותו לתת ולקחת ללא הסבר.","השטן הוא האחראי הבלעדי לסבל, ואלוהים יפצה את איוב בעתיד."],correctAnswer:2,explanation:"איוב מציג קבלה של ריבונות אלוהית מוחלטת: הכול שייך לאל, והוא רשאי לתת ולקחת."},{question:"בנאום הפתיחה של איוב (פרק ג'), מהו המוטיב המרכזי שדרכו הוא מבטא את סבלו?",options:["בקשה מאלוהים שיסביר לו על מה הוא נענש כדי שיוכל לחזור בתשובה.","קללת יום היוולדו והבעת משאלה שהעולם יחזור למצב של תוהו ובוהו.","האשמת הרעים בכך שהם לא תומכים בו בשעתו הקשה ביותר.","תיאור מפורט של המחלות הגופניות שפגעו בו והכאב הפיזי הבלתי נסבל."],correctAnswer:1,explanation:"איוב מקלל את יום לידתו ומבטא משאלה לביטול סדר הבריאה כתגובה לעוצמת הסבל."},{question:'מהי "משוואת הגמול" (תורת הגמול) המנחה את דברי הרעים לאורך הספר?',options:["אלוהים פועל בצורה שרירותית שאינה מובנת לבני האדם.","הצדיק סובל בגלל חטאי הדור, והרשע מצליח כדי להטעות אחרים.","יש קשר ישיר והכרחי בין מעשי האדם (צדק או חטא) לגורלו (שכר או עונש).","הסבל בעולם הוא תוצאה של כוחות רשע הנלחמים בכוחות הטוב."],correctAnswer:2,explanation:"זו נוסחת הליבה של הרעים: צדקות מביאה טוב וחטא מביא עונש, בקשר הכרחי וישיר."},{question:"מהו הטיעון המרכזי של אליפז התימני בנאומו הראשון כלפי איוב?",options:["אין אדם צדיק בארץ אשר יעשה טוב ולא יחטא, ולכן גם איוב אשם במשהו.","איוב חייב לשתוק ולקבל את הדין באהבה כי הסבל ממרק עוונות.","הרעים יודעים בדיוק מהו החטא של איוב ודורשים ממנו להתוודות עליו.","אלוהים אינו מתעניין במעשי בני האדם כי הם קטנים מדי עבורו."],correctAnswer:0,explanation:"אליפז מדגיש שאין אנוש נקי לגמרי לפני האל, ולכן גם סבלו של איוב נתפס כבעל בסיס מוסרי."},{question:`מה מבקש איוב להמחיש באמצעות "משל ההרים המושלגים" (פרק ו')?`,options:["את עוצמת הטבע לעומת חולשת האדם מול איתני הסביבה.","את האכזבה שלו מהרעים, שהיו אמורים להיות מקור תמיכה והכזיבו.","את הקור הפיזי שהוא מרגיש בעקבות המחלה שפשטה בגופו.","את הטוהר של נשמתו, שהיא לבנה ונקייה מחטא כמו השלג."],correctAnswer:1,explanation:"המשל מתאר מקורות מים מאכזבים וכך גם את החברים שלא עמדו במבחן החמלה בשעת מצוקה."},{question:`בנאומו לאליפז (פרק ז'), איוב משתמש בפרפרזה על תהילים ח' ("מה אנוש כי תזכרנו"). מהי מטרתו?`,options:["להלל את אלוהים על כך שהוא משגיח על האדם באופן אישי וקרוב.","להראות שהאדם הוא נזר הבריאה ולכן מגיע לו יחס מיוחד מהאל.",'לתהות מדוע אלוהים "נטפל" ליצור קטן וזמני כמו האדם ורודף אותו.','להוכיח שהתנ"ך כולו תומך בגישה שאיוב הוא צדיק גמור.'],correctAnswer:2,explanation:"איוב הופך את לשון המזמור לשאלת מחאה: למה השגחה על האדם נחווית כמעקב מכאיב ורודף."},{question:"מהי עמדת בלדד השוחי בנוגע למות בני איוב?",options:["בני איוב מתו כחלק מניסיון שאלוהים מעמיד בו את איוב.","מות הבנים הוא הוכחה לכך שהם חטאו, שכן אלוהים לא מעוות משפט.","המוות הוא מקרי ואינו קשור להתנהגות המוסרית של הבנים.","איוב צריך לשמוח שבניו מתו מוות מהיר ולא סבלו כמוהו."],correctAnswer:1,explanation:"בלדד מחזיק בעמדה קשוחה של גמול: אם נפגעו, סימן שחטאו, כי האל אינו מעוות משפט."},{question:'מהו "המודל המשפטי" שאיוב מנסה להחיל על יחסיו עם אלוהים?',options:["הוא מבקש עורך דין (מליץ) שיגן עליו בפני בית דין של מעלה.","הוא דורש כתב אישום מסודר כדי שיוכל להתגונן ולהוכיח את חפותו.","הוא מנסה להגיע לפשרה מחוץ לכותלי בית המשפט באמצעות תפילה.","הוא טוען שאלוהים אינו כפוף לחוקי הצדק ולכן אין טעם במשפט."],correctAnswer:1,explanation:"איוב דורש הליך משפטי ברור עם פירוט אשמות, כדי שתהיה לו אפשרות ממשית להתגונן."},{question:"צופר הנעמתי מציג עמדה קיצונית לגבי חכמת האלוהים. מהי?",options:["חכמת האדם שווה לחכמת האלוהים אם האדם לומד מספיק תורה.","חכמת אלוהים היא נסתרת, וייתכן שאיוב נענש פחות ממה שמגיע לו באמת.","אלוהים מחלק את החכמה רק לצדיקים, ולכן איוב אינו חכם עוד.","אין בעולם צדק גלוי, והכל תלוי במזל ובמקריות בלבד."],correctAnswer:1,explanation:"צופר מדגיש שהחכמה האלוהית נשגבת מהאדם ואף טוען שאיוב קיבל עונש קל יחסית לעוונו."},{question:'מהי "שבועת החפות" של איוב בנאומי הסיכום שלו (פרק ל"א)?',options:["רשימה של חטאים פוטנציאליים שאיוב נשבע שלא ביצע מעולם.","בקשת סליחה כללית על כל חטא שייתכן ועשה בטעות בצעירותו.","הצהרה שהרעים הם אלו שחטאו וצריכים להיענש במקומו.","נכונות לקבל את כל הייסורים בתנאי שאלוהים יחזיר לו את עושרו."],correctAnswer:0,explanation:"שבועת הניקוי בנויה כרשימת סעיפים מוסריים שאיוב מצהיר שלא עבר עליהם."},{question:"בתשובת האל מן הסערה, אלוהים מציג לא איוב שאלות על עולם הטבע. מה המסר?",options:["אלוהים מוכיח לא איוב שהוא דואג לכל חיה וחיה, ולכן ידאג גם לו.","אלוהים מראה לא איוב שהאדם אינו מרכז העולם ואין לו הבנה בניהול היקום.","אלוהים מסביר שחוקי המוסר בטבע הם אלו שצריכים להנחות את האדם.","אלוהים מבקש מאיוב לעזור לו בניהול כוחות הטבע (הלווייתן והבהמות)."],correctAnswer:1,explanation:"השאלות מן הסערה מציבות את איוב מול גבולות הידיעה האנושית ומערערות אנתרופוצנטריות."},{question:"על פי פרשנותו של מתתיהו צבת, מהי המשמעות של עצם פניית ה' לאיוב?",options:["הוכחה לכך שתורת הגמול של הרעים הייתה נכונה מיסודה.","עדות להשגחה פרטית – עצם העובדה שה' עונה מעידה על קשר עם האדם.","הוכחה שאיוב אכן חטא, שכן אלוהים לא מופיע בפני צדיקים גמורים.","סימן לכך שאלוהים עומד לבטל את הסבל בעולם באופן סופי."],correctAnswer:1,explanation:"לפי הקריאה הזאת, עצם המענה האלוהי מעיד שלא מדובר בניתוק מוחלט בין האל לבין האדם הסובל."},{question:"מהי נקודת התורפה בשיטת מתתיהו צבת לגבי תשובת האל, כפי שמופיע בסיכום?",options:["אלוהים מתעלם לחלוטין משאלותיו של איוב על הצדק והמוסר.",'בסוף הנאום יש "מובלעות" של תורת הגמול (ענישת רשעים) שסותרות את התזה המרכזית.',"התיאורים של הלווייתן והבהמות הם אגדיים מדי ואינם מתאימים להקשר המקראי.","איוב אינו משתכנע מדברי האל וממשיך להתווכח איתו גם בסוף הספר."],correctAnswer:1,explanation:"ביקורת מרכזית על צבת היא קיומם של פסוקים עם נופך גמולי שמחלישים את הטענה לעולם א-מוסרי לגמרי."},{question:`כיצד גרינשטיין מפרש את "התבנית המשפטית" במענה ה'?`,options:["ה' טוען שאיוב אינו יכול להעיד נגדו כי הוא אינו עד אמין או מוסמך.","ה' מודה בטעותו המשפטית ומציע לא איוב פיצוי כספי כפול.","המשפט מסתיים בזיכוי מוחלט של איוב מכל אשמה פלילית או מוסרית.","ה' קובע שהרעים הם העדים המרכזיים ואיוב הוא הנאשם העיקרי."],correctAnswer:0,explanation:"לפי גרינשטיין, המענה האלוהי פועל כמהלך פורנזי שמערער את כשירותו של איוב כעד."},{question:'מהו תפקידו של המלאך "השטן" בפרקי הפתיחה?',options:["כוח עצמאי ומרושע שנלחם באלוהים ומנסה להחריב את העולם.",'מעין "קטיגור" בשירות האל שתפקידו לבחון את כנות צדקתם של בני האדם.',"ייצוג של יצר הרע השוכן בתוך לבו של איוב עצמו ומייסר אותו.","מלאך שומר שנשלח להגן על איוב אך נכשל במשימתו בגלל חטאי הדור."],correctAnswer:1,explanation:"השטן מתואר כתפקיד במערך השמימי ולא ככוח אלטרנטיבי עצמאי מול האל."},{question:`מדוע נחשבת דמותו של איוב בפרקים ג'-ל"א לניגוד של דמותו באקספוזיציה?`,options:["באקספוזיציה הוא עשיר מאוד, ובפרקי השירה הוא הופך לעני מרוד.","באקספוזיציה הוא פסיבי ומקבל את הדין, ובשירה הוא אקטיבי, מורד וזועק.","באקספוזיציה הוא גר בארץ עוץ, ובפרקי השירה הוא עובר לירושלים.","באקספוזיציה הוא מדבר בשפה פשוטה, ובשירה הוא משתמש בשפה ארמית."],correctAnswer:1,explanation:"במעבר לפרקי השירה איוב משנה קול: מקבלה שקטה למחאה פעילה ותביעה משפטית."},{question:'בנאומיו, איוב מתאר את אלוהים לעיתים כ"צייד" או "אויב". מה זה מבטא?',options:["את חוסר האמונה המוחלט של איוב בקיומו של כוח עליון בעולם.","את התחושה שאלוהים רודף אותו אישית בצורה לא הוגנת וללא סיבה.","את הרצון של איוב להילחם באלוהים פיזית כדי להוכיח את כוחו.","את ההכרה בכך שהטבע הוא מקום אלים ומסוכן לכל יצור חי."],correctAnswer:1,explanation:"הדימוי מבטא חוויית רדיפה אישית ויחס עוין מצד האל, לא כפירה בעצם קיומו."},{question:'מהי הביקורת של איוב על דברי הרעים בנוגע ל"צדיק וטוב לו, רשע ורע לו"?',options:["הוא טוען שהם לא מכירים מספיק את המציאות שבה רשעים חיים בשלווה.","הוא טוען שהרעים בעצמם חוטאים ולכן אין להם זכות להטיף מוסר.","הוא טוען שתורת הגמול תתקיים רק בעולם הבא ולא בעולם הזה.","הוא מסכים איתם עקרונית, אך טוען שהוא המקרה החריג היחיד בהיסטוריה."],correctAnswer:0,explanation:"איוב מציג נגד הרעים תצפית אמפירית: במציאות נראים גם רשעים שמצליחים לאורך זמן."},{question:'בפרק כ"ח (מזמור החכמה), מהי המסקנה לגבי היכולת להבין את דרכי האל?',options:["החכמה נמצאת אצל הפילוסופים הגדולים של יוון ומצרים.","החכמה היא נסתרת מהאדם, ורק ה' יודע את מקומה.","האדם יכול להגיע לחכמה אם יחקור לעומק את מכרות הזהב והכסף.","יראת ה' היא החכמה, ואין טעם לנסות להבין את סודות הבריאה."],correctAnswer:1,explanation:"המזמור קובע שמקומה של החכמה נשגב מן האדם, ורק האל יודע אותה במלואה."},{question:"מה קורה לאיוב בסיום הספר (האפילוג)?",options:["הוא מת בשיבה טובה מבלי לקבל חזרה את מה שאיבד.","אלוהים מחזיר לו את עושרו ומשפחתו פי שניים ממה שהיה לו.","הוא הופך לנביא ומלמד את הרעים איך לעבוד את ה' בצורה נכונה.","הוא נשאר במצבו הקשה אך מוצא שלווה פנימית בזכות המפגש עם האל."],correctAnswer:1,explanation:"האפילוג מתאר שיקום חומרי ומשפחתי כפול ביחס למצבו הקודם של איוב."},{question:"מהו היחס של אלוהים לרעים בסוף הספר?",options:["הוא משבח אותם על כך שהגנו על כבודו ועל תורת הגמול שלו.",'הוא כועס עליהם כי לא דיברו עליו "נכונה" כמו איוב, ודורש שיקריבו קורבנות.',"הוא מעניש אותם באותן מחלות שבהן לקה איוב כדי שילמדו לקח.","הוא מתעלם מהם לחלוטין ומתמקד רק בשיקום חייו של איוב."],correctAnswer:1,explanation:"בסיום הספר האל דוחה את עמדת הרעים ומחייב אותם בקורבן ובתפילת איוב בעדם."},{question:"מהי התזה המרכזית של ספר איוב לגבי הסבל בעולם?",options:["סבל הוא תמיד תוצאה של חטא, גם אם הוא נסתר מעין האדם.","העולם מנוהל על ידי מערכת מוסרית אנושית שניתן להבין בשכל.","הסבל הוא תעלומה, ואלוהים גדול יותר מהתפיסות המוסריות המצומצמות של האדם.","האדם צריך להפסיק לשאול שאלות ולהתמקד רק בקיום המצוות המעשיות."],correctAnswer:2,explanation:"הספר מערער על גמול פשטני ומציג פער עמוק בין המורכבות האלוהית לבין הקטגוריות האנושיות."},{question:'מדוע איוב נחשב ל"גיבור טרגי" על פי חלק מהפרשנויות?',options:["כי הוא גורם להרס משפחתו בגלל טעות קטנה שעשה בצעירותו.","כי הוא נלחם על הצדק שלו מול כוח עליון בידיעה מראש שאין לו סיכוי לנצח.","כי הוא מת בסוף הסיפור בודד ועזוב ללא הכרה בחפותו.","כי הוא מאבד את שפיות דעתו בעקבות הייסורים הקשים שעבר."],correctAnswer:1,explanation:"איוב נתפס כטרגי משום שהוא נאבק בעקביות על אמתו מול פער כוחות קיצוני וחסר פתרון מלא."}];export{o as q};
